package com.example.yuejie;
import android.app.*;import android.os.*;import org.json.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Real backend read-only integration. Does not add books or write reading progress. */
public final class CommentLiveChecks extends Instrumentation {
 public void onCreate(Bundle args){super.onCreate(args);start();}
 public void onStart(){CommentExecutor worker=new CommentExecutor();LocalLibrary library=new LocalLibrary(getTargetContext());try{
  String book="7383244104223689790",chapter="7383333629616718398";JSONObject before=library.progress(book);NovelApi novel=new NovelApi(getTargetContext(),library);JSONObject body=novel.chapter(book,chapter);ParagraphCommentApi api=new ParagraphCommentApi(getTargetContext(),library);JSONObject meta=api.metadata(book,chapter),stats=api.stats(book,chapter,meta.getString("item_version"));JSONObject chosen=null;JSONArray paragraphs=meta.getJSONArray("paragraph_meta");for(int i=0;i<paragraphs.length();i++){JSONObject p=paragraphs.getJSONObject(i);if(stats.optLong(p.getString("id"))>0){chosen=p;break;}}if(chosen==null)throw new AssertionError("live commented paragraph missing");
  CommentPages.Scope scope=new CommentPages.Scope(book,chapter,meta.getString("item_version"),chosen.getString("id"),chosen.getString("text"));CommentPages pages=new CommentPages(api,worker);AtomicReference<JSONObject> value=new AtomicReference<>();AtomicReference<Exception> error=new AtomicReference<>();CountDownLatch done=new CountDownLatch(1);pages.request(scope,"",CommentExecutor.USER,true,()->true,(result,problem)->{value.set(result);error.set(problem);done.countDown();});if(!done.await(150,TimeUnit.SECONDS))throw new AssertionError("live first-page timeout");if(error.get()!=null)throw error.get();if(value.get()==null||value.get().getJSONArray("items").length()==0)throw new AssertionError("live comments missing");
  Bundle status=new Bundle();status.putString("stream","PASS Android real HTTPS body, validated mapping, stats and single-flight first page: "+value.get().getJSONArray("items").length()+" comments\n");sendStatus(0,status);
  if(pages.cached(scope,"")==null)throw new AssertionError("live first page was not cached");if(!body.optString("text").equals(meta.optString("text")))throw new AssertionError("mapping differs from current body");JSONObject after=library.progress(book);if(before==null?after!=null:!before.toString().equals(after.toString()))throw new AssertionError("live comment read changed progress");Bundle result=new Bundle();result.putString("stream","PASS live text cache and unchanged reading progress");finish(0,result);
 }catch(Throwable e){Bundle result=new Bundle();result.putString("stream","FAIL "+android.util.Log.getStackTraceString(e));finish(1,result);}finally{worker.shutdownNow();library.close();}}
}
